import java.util.Scanner;

class Member {
    String memberId;
    String name;
    String email;
    int maxLoan;

    // Constructor 1 (memberId, name, email): maxLoan = 3. Constructor 2 (ditambah maxLoan): panggil constructor 1 dengan this(...), lalu isi maxLoan.
    Member(String memberId, String name, String email) {
    }

    Member(String memberId, String name, String email, int maxLoan) {
    }

    String getSummary() {
        return memberId + " - " + name + " (maks " + maxLoan + " buku)";
    }

    boolean canBorrow(int loanCountNow) {
        // Kembalikan true bila loanCountNow lebih kecil dari maxLoan.
        return false;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        String id = in.nextLine().trim();
        String name = in.nextLine().trim();
        String email = in.nextLine().trim();
        String batas = in.nextLine().trim();
        int loans = Integer.parseInt(in.nextLine().trim());
        Member m;
        if (batas.equals("-")) {
            m = new Member(id, name, email);
        } else {
            m = new Member(id, name, email, Integer.parseInt(batas));
        }
        System.out.println(m.getSummary());
        System.out.println("Boleh meminjam: " + m.canBorrow(loans));
    }
}
